class HubAppBar extends StatelessWidget implements PreferredSizeWidget {
  const HubAppBar({
    super.key,
    required this.title,
    this.onBack,
    this.trailing,
    this.titleColor,
  });

  final String title;
  final VoidCallback? onBack;
  final Widget? trailing;
  final Color? titleColor;

  @override
  Size get preferredSize => const Size.fromHeight(56);

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      bottom: false,
      child: SizedBox(
        height: 56,
        child: Row(
          children: [
            IconButton(
              onPressed: onBack ?? () => Navigator.maybePop(context),
              icon: const Icon(Icons.arrow_back_ios_new_rounded, size: 18),
            ),
            Expanded(
              child: Text(
                title,
                textAlign: TextAlign.center,
                style: GoogleFonts.michroma(
                  color: titleColor ?? AppColors.textPrimary,
                  fontSize: 18,
                  letterSpacing: 2,
                ),
              ),
            ),
            trailing ??
                IconButton(
                  onPressed: () {},
                  icon: const Icon(Icons.smart_toy_outlined, size: 22),
                ),
          ],
        ),
      ),
    );
  }
}

class GenotypePhenotypeToggle extends StatelessWidget {
  const GenotypePhenotypeToggle({
    super.key,
    required this.isPhenotype,
    required this.onChanged,
  });

  final bool isPhenotype;
  final ValueChanged<bool> onChanged;

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 40,
      margin: const EdgeInsets.symmetric(horizontal: 48),
      decoration: BoxDecoration(
        color: AppColors.surfaceElevated,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: AppColors.border),
      ),
      child: Row(
        children: [
          _seg('Genotype', !isPhenotype, () => onChanged(false)),
          _seg('Phenotype', isPhenotype, () => onChanged(true)),
        ],
      ),
    );
  }

  Widget _seg(String label, bool active, VoidCallback onTap) {
    return Expanded(
      child: GestureDetector(
        onTap: onTap,
        child: AnimatedContainer(
          duration: 220.ms,
          margin: const EdgeInsets.all(3),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(20),
            gradient: active
                ? LinearGradient(
                    colors: [
                      AppColors.neonGreen.withValues(alpha: 0.25),
                      AppColors.surface,
                    ],
                  )
                : null,
            border: active
                ? Border.all(color: AppColors.neonGreen.withValues(alpha: 0.5))
                : null,
          ),
          child: Text(
            label,
            style: GoogleFonts.michroma(
              fontSize: 11,
              color: active ? AppColors.neonGreen : AppColors.textSecondary,
              letterSpacing: 0.8,
            ),
          ),
        ),
      ),
    );
  }
}

class CalloutBubble extends StatelessWidget {
  const CalloutBubble({
    super.key,
    required this.info,
    this.onDetails,
  });

  final CalloutInfo info;
  final VoidCallback? onDetails;

  @override
  Widget build(BuildContext context) {
    final color = info.isPositive ? AppColors.neonGreen : AppColors.orange;
    return Container(
      constraints: const BoxConstraints(maxWidth: 150),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
      decoration: BoxDecoration(
        color: Colors.black.withValues(alpha: 0.72),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: color.withValues(alpha: 0.85)),
        boxShadow: [
          BoxShadow(color: color.withValues(alpha: 0.25), blurRadius: 12),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            info.text,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 10,
              height: 1.25,
            ),
          ),
          if (info.detailLink) ...[
            const SizedBox(height: 4),
            GestureDetector(
              onTap: onDetails,
              child: Text(
                'View in Details ->',
                style: TextStyle(
                  color: color,
                  fontSize: 10,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }
}

class HolographicOrganStage extends StatelessWidget {
  const HolographicOrganStage({
    super.key,
    required this.asset,
    required this.callouts,
    this.height = 280,
    this.onDetails,
  });

  final String asset;
  final List<CalloutInfo> callouts;
  final double height;
  final VoidCallback? onDetails;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: height,
      child: Stack(
        alignment: Alignment.center,
        children: [
          Positioned(
            bottom: 10,
            left: 24,
            right: 24,
            height: 120,
            child: CustomPaint(
              painter: HolographicBasePainter(),
            ),
          ),
          Positioned(
            bottom: 48,
            child: Image.asset(
              asset,
              height: height * 0.62,
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => Icon(
                Icons.favorite,
                size: 120,
                color: AppColors.red.withValues(alpha: 0.8),
              ),
            ).animate().fadeIn(duration: 500.ms).scale(
                  begin: const Offset(0.92, 0.92),
                  end: const Offset(1, 1),
                  duration: 600.ms,
                ),
          ),
          ..._positionedCallouts(),
        ],
      ),
    );
  }

  List<Widget> _positionedCallouts() {
    return callouts.map((c) {
      Alignment alignment;
      EdgeInsets padding;
      switch (c.alignment) {
        case CalloutAlign.topLeft:
          alignment = Alignment.topLeft;
          padding = const EdgeInsets.only(left: 8, top: 24);
        case CalloutAlign.topRight:
          alignment = Alignment.topRight;
          padding = const EdgeInsets.only(right: 8, top: 20);
        case CalloutAlign.bottomLeft:
          alignment = Alignment.bottomLeft;
          padding = const EdgeInsets.only(left: 8, bottom: 70);
        case CalloutAlign.bottomRight:
          alignment = Alignment.bottomRight;
          padding = const EdgeInsets.only(right: 8, bottom: 70);
        case CalloutAlign.midRight:
          alignment = Alignment.centerRight;
          padding = const EdgeInsets.only(right: 4);
      }
      return Align(
        alignment: alignment,
        child: Padding(
          padding: padding,
          child: CalloutBubble(info: c, onDetails: onDetails),
        ),
      );
    }).toList();
  }
}

class AnimatedScoreRing extends StatelessWidget {
  const AnimatedScoreRing({
    super.key,
    required this.score,
    required this.accent,
    this.size = 220,
  });

  final double score;
  final Color accent;
  final double size;

  @override
  Widget build(BuildContext context) {
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0, end: score / 100),
      duration: const Duration(milliseconds: 1200),
      curve: Curves.easeOutCubic,
      builder: (context, value, _) {
        return SizedBox(
          width: size,
          height: size,
          child: Stack(
            alignment: Alignment.center,
            children: [
              CustomPaint(
                size: Size(size, size),
                painter: ScoreRingPainter(progress: value, accent: accent),
              ),
              Text(
                '${(value * 100).round()}%',
                style: GoogleFonts.michroma(
                  fontSize: size * 0.16,
                  color: Colors.white,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

