                        const SizedBox(height: 16),
                        MarkerChipGrid(
                          title: 'Strengths :',
                          items: data.strengths,
                          color: AppColors.neonGreen,
                        ),
                        const SizedBox(height: 16),
                        MarkerChipGrid(
                          title: 'Weakness :',
                          items: data.weaknesses,
                          color: AppColors.red,
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              if (menuOpen)
                Positioned(
                  top: 108,
                  right: 10,
                  child: OrganMetricsMenu(
                    selectedId: selectedOrgan,
                    onSelect: (id) {
                      setState(() {
                        selectedOrgan = id;
                        menuOpen = false;
                      });
                      context.push('/organ/$id');
                    },
                    onBloodMetrics: () => context.push('/metric/mentzer'),
                    onHormone: () => context.push('/organ/brain'),
                  ).animate().fadeIn(duration: 250.ms).slideX(begin: 0.15),
                ),
              Positioned(
                top: 108,
                right: 12,
                child: menuOpen
                    ? const SizedBox.shrink()
                    : FloatingActionButton.small(
                        backgroundColor: AppColors.surfaceElevated,
                        onPressed: () => setState(() => menuOpen = true),
                        child: const Icon(Icons.menu_open_rounded),
                      ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _bodyStage() {
    return SizedBox(
      height: 320,
      child: Stack(
        alignment: Alignment.center,
        children: [
          Positioned(
            bottom: 20,
            left: 20,
            right: 20,
            height: 140,
            child: CustomPaint(painter: HolographicBasePainter()),
          ),
          Positioned(
            bottom: 70,
            child: Image.asset(
              'assets/images/Frame 1321314327.png',
              height: 230,
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => const Icon(
                Icons.accessibility_new,
                size: 180,
                color: AppColors.cyan,
              ),
            ),
          ),
          ...DummyHealthData.overview.bodyIssues.map((c) {
            return Align(
              alignment: c.alignment == CalloutAlign.midRight
                  ? Alignment.centerRight
                  : c.alignment == CalloutAlign.bottomLeft
                      ? Alignment.bottomLeft
                      : Alignment.topLeft,
              child: Padding(
                padding: const EdgeInsets.all(8),
                child: CalloutBubble(
                  info: c,
                  onDetails: () => context.push('/organ/lungs'),
                ),
              ),
            );
          }),
        ],
      ),
    );
  }

  Widget _neuroToggle() {
    return Container(
      height: 36,
      width: 220,
      decoration: BoxDecoration(
        color: AppColors.surfaceElevated,
        borderRadius: BorderRadius.circular(20),
      ),
      child: Row(
        children: [
          Expanded(
            child: _chip('Dopamine', !serotonin, () {
              setState(() => serotonin = false);
            }),
          ),
          Expanded(
            child: _chip('Serotonin', serotonin, () {
              setState(() => serotonin = true);
            }, activeColor: AppColors.neonGreen),
          ),
        ],
      ),
    );
  }

  Widget _chip(
    String label,
    bool active,
    VoidCallback onTap, {
    Color activeColor = const Color(0xFF2A2A2A),
  }) {
    return GestureDetector(
      onTap: onTap,
      child: AnimatedContainer(
        duration: 200.ms,
        margin: const EdgeInsets.all(3),
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: active ? activeColor : Colors.transparent,
          borderRadius: BorderRadius.circular(16),
        ),
        child: Text(
          label,
          style: TextStyle(
            color: active && activeColor == AppColors.neonGreen
                ? Colors.black
                : Colors.white,
            fontWeight: FontWeight.w600,
            fontSize: 12,
          ),
        ),
      ),
    );
  }

  Widget _aboutRow(double score, String about) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          width: 120,
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: AppColors.card,
            borderRadius: BorderRadius.circular(14),
            border: Border.all(color: AppColors.cyan.withValues(alpha: 0.35)),
          ),
          child: Column(
            children: [
              Text(
                'Hyperprolactinemia Score',
                textAlign: TextAlign.center,
                style: GoogleFonts.michroma(fontSize: 8, color: Colors.white70),
              ),
              const SizedBox(height: 8),
              const Icon(Icons.biotech, color: AppColors.cyan, size: 34),
              const SizedBox(height: 8),
              Text(
                '${score.toStringAsFixed(0)}%',
                style: GoogleFonts.michroma(fontSize: 22, color: Colors.white),
              ),
              const Text(
                'Blood levels',
                style: TextStyle(color: AppColors.textMuted, fontSize: 10),
              ),
            ],
          ),
        ),
        const SizedBox(width: 12),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'ABOUT Hyperprolactinemia',
                style: GoogleFonts.michroma(fontSize: 11, color: Colors.white),
              ),
              const SizedBox(height: 8),
              Text(
                about,
                style: const TextStyle(
                  color: AppColors.textSecondary,
                  fontSize: 12,
                  height: 1.4,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

